def compute(vars):
    total = vars["v1"] + vars["v2"] - vars["v3"]
    return {
        "value": total,
        "trace": {
            "reconstruction_costs": vars["v1"],
            "transaction_costs": vars["v2"],
            "deferred_income_tax_benefits": vars["v3"],
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
